package org.apache.commons.cli;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class CommandLine_hasOption_TriageGen1Test {
    private CommandLine cmd;

    @Before
    public void setup() {
        String[] args = {"-a", "-b", "-c"};
        cmd = new CommandLine(new Options());
        cmd.parse(args);
    }

    @Test
    public void testHasOption_String() {
        assertTrue(cmd.hasOption("a"));
        assertTrue(cmd.hasOption("b"));
        assertTrue(cmd.hasOption("c"));
        assertFalse(cmd.hasOption("d"));
        assertFalse(cmd.hasOption(""));
        assertFalse(cmd.hasOption(null));
    }

    @Test
    public void testHasOption_char() {
        assertTrue(cmd.hasOption('a'));
        assertTrue(cmd.hasOption('b'));
        assertTrue(cmd.hasOption('c'));
        assertFalse(cmd.hasOption('d'));
        assertFalse(cmd.hasOption('0'));
    }

    @Test
    public void testHasOption_Null() {
        CommandLine cmd = new CommandLine(new Options());
        assertTrue(cmd.hasOption(null));
    }

    @Test
    public void testHasOption_EmptyString() {
        CommandLine cmd = new CommandLine(new Options());
        assertTrue(cmd.hasOption(""));
    }

    @Test
    public void testHasOption_OptionsWithDuplicates() {
        Options options = new Options();
        options.addOption("a");
        options.addOption("a");
        CommandLine cmd = new CommandLine(options);
        cmd.addOption("a");
        assertTrue(cmd.hasOption("a"));
    }

    @Test
    public void testHasOption_OptionsWithSameName() {
        Options options = new Options();
        options.addOption("a");
        options.addOption("b");
        CommandLine cmd = new CommandLine(options);
        cmd.addOption("a");
        assertTrue(cmd.hasOption("a"));
        assertTrue(cmd.hasOption("b"));
    }

    @Test
    public void testHasOption_OptionsWithNoOptions() {
        CommandLine cmd = new CommandLine(new Options());
        assertFalse(cmd.hasOption("a"));
    }

    @Test
    public void testHasOption_OptionsWithNoOptionsAndNull() {
        CommandLine cmd = new CommandLine(new Options());
        assertFalse(cmd.hasOption(null));
    }

    @Test
    public void testHasOption_OptionsWithNoOptionsAndEmptyString() {
        CommandLine cmd = new CommandLine(new Options());
        assertFalse(cmd.hasOption(""));
    }

    @Test
    public void testHasOption_OptionsWithNoOptionsAndValidOption() {
        CommandLine cmd = new CommandLine(new Options());
        assertFalse(cmd.hasOption("a"));
    }
}
